// CSD_RATIONALE_BEGIN
// Simple delimiter-triggered CSD. Generate freely until "<<" appears, then
// constrain until the parser says the span can close.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
