// Refinement mode: valid-basin surgical verification repair. Preserve the
// evidence-backed decoding ingredients from the balanced-best basin: mostly
// free token-wise generation outside spans, no extra entry heuristic beyond
// observed delimiter entry, hard parser-valid token progression inside the core
// span with adaptive/group-aware preference, and immediate close on complete
// constrained prefixes. The measured failure source is purely contractual:
// Dafny could not prove the final "some progress when maxSteps > 0" disjunct.
// This repair changes only that causal axis by adding an explicit
// madeProgress flag that is set exactly when cost becomes positive or any
// visible/state output changes. The decoding behavior remains essentially the
// balanced-best strategy, while the progress fact becomes a maintained loop
// invariant and therefore easy to discharge at return.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Outside free-token branch: if EOS is sampled we break without changing
//   insideConstrainedOut/currentConstrainedOut, so validity is preserved. If a
//   non-EOS token is appended and it is not "<<", we remain outside and the
//   implication is vacuous. If it is "<<", we enter constrained mode with
//   currentConstrainedOut := [], which is valid by parser.IsValidPrefix([]).
// - Close branch: this branch is taken only when parser.IsCompletePrefix holds;
//   CloseConstrainedSpan exits constrained mode and clears currentConstrainedOut,
//   so the implication becomes vacuous afterward.
// - Inside decoding branch: AdaptiveConstrainedStep consumes one token-step and
//   returns either EOS or a parser-valid next token under hard masking. On EOS
//   we break without changing constrained state; otherwise
//   AppendConstrainedToken extends currentConstrainedOut by that valid token,
//   preserving parser.IsValidPrefix.
//
// progress:
// - Outside free-token branch: UnconstrainedStep consumes exactly one step. EOS
//   may append nothing; otherwise at most one visible token is appended. After
//   steps := steps + 1, the bound |generated| <= |generatedPrefix| + steps is
//   preserved.
// - Close branch: CloseConstrainedSpan consumes one token-step and appends at
//   most one visible close delimiter, so incrementing steps by 1 preserves the
//   bound.
// - Inside decoding branch: AdaptiveConstrainedStep consumes one token-step. If
//   it returns EOS, visible output does not grow; otherwise AppendConstrainedToken
//   appends exactly the already-paid-for token. Hence visible growth is at most
//   the consumed token budget.
// - The madeProgress invariant is preserved branchwise: whenever steps becomes
//   positive we set madeProgress := true; delimiter observation, constrained
//   entry, token append, and close also set it true because output/state has
//   changed. Thus on loop exit, if maxSteps > 0 and no output/state changed,
//   madeProgress can still only hold because cost > 0, which is enough for the
//   required postcondition disjunction.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;
var madeProgress: bool := false;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant madeProgress ==> steps > 0 || generated != generatedPrefix ||
                              insideConstrainedOut != insideConstrained ||
                              currentConstrainedOut != currentConstrained
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    madeProgress := true;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    madeProgress := true;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    madeProgress := true;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

