//   holds. CloseConstrainedSpan exits constrained mode and clears the tracked
//   constrained contents, so !insideConstrainedOut holds afterward and the
//   implication is vacuous.
// - Inside adaptive branch: AdaptiveConstrainedStep returns either EOS or a
//   parser-valid next token under a hard parser mask. On EOS we break without
//   changing currentConstrainedOut; otherwise AppendConstrainedToken appends the
//   already-valid token to both generated and currentConstrainedOut, preserving
//   parser.IsValidPrefix(currentConstrainedOut).
//
// progress:
// - Free outside branch: UnconstrainedStep consumes exactly one token-step. If
//   it returns EOS, no visible token is appended and the bound is preserved
//   after steps := steps + 1. Otherwise exactly one visible token is appended,
//   so visible growth is at most the consumed budget.
// - Close branch: CloseConstrainedSpan consumes one token-step and appends at
//   most one visible close delimiter, so after steps := steps + 1 we still have
//   |generated| <= |generatedPrefix| + steps.
// - Inside adaptive branch: AdaptiveConstrainedStep consumes one token-step,
//   including the EOS case. If EOS is returned, visible output does not grow;
//   otherwise AppendConstrainedToken appends exactly one visible token. Thus
//   visible growth is at most the one token-step charged to steps.
// - Progress postcondition: every non-break branch that changes visible output
//   or span state uses a helper with positive token-step cost, so if maxSteps > 0
//   and execution changes state then either cost > 0 or a counted step already
//   witnessed the change.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;
